&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Mistral&lt;/td&gt;
&lt;td&gt;mistral-large-2512&lt;/td&gt;
&lt;td&gt;model only&lt;/td&gt;
&lt;td&gt;glossary + brand voice + instructions&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Deepseek&lt;/td&gt;
&lt;td&gt;deepseek-v3.2&lt;/td&gt;
