&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;
&lt;a href="https://blog.google/" rel="noopener noreferrer"&gt;blog.google at 1025px&lt;/a&gt; 😥&lt;/td&gt;
&lt;td&gt;&lt;img src="https://media2.dev.to/dynamic/image/width=800%2Cheight=%2Cfit=scale-down%2Cgravity=auto%2Cformat=auto/https%3A%2F%2Fdev-to-uploads.s3.amazonaws.com%2Fuploads%2Farticles%2F01l0jhiuypo1b20mted7.png" alt="Google Blog navbar overflowing around 1025px" width="800" height="143"&gt;&lt;/td&gt;
